Translate("deDE", "mulgore", {
	title = "Mulgore",
	aliases = { "die Ebenen von Mulgore" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Mulgore ist die Heimat der {link:tauren}Tauren{/link}, ein weites Land aus goldenem Gras und sanften Hügeln, auf allen Seiten von Bergen umschlossen. Kodoherden weiden auf seinen Ebenen, und klare Brunnen und Seen tränken das Land. Über allem erheben sich die großen Tafelberge von {link:thunder-bluff}Thunder Bluff{/link}, der {link:capital-city}Hauptstadt{/link} der Tauren, wo der Hochhäuptling {link:cairne-bloodhoof}Cairne Bloodhoof{/link} seine Halle hat. Für die Tauren ist dies das Geschenk der {red:earth-mother}Erdenmutter{/red}, ein friedliches Land nach Jahrhunderten der Wanderschaft. Doch {link:quilboar}Stacheleber{/link}, {link:gnolls}Gnolle{/link}, {link:harpies}Harpyien{/link} und Goblins drängen von allen Rändern herein, und die Jungen der Stämme müssen sich gegen sie bewähren.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Unzählige Generationen lang waren die {link:tauren}Tauren{/link} Nomaden, die den Herden über die Ebenen von {link:kalimdor}Kalimdor{/link} folgten. Die {link:centaurs}Zentauren{/link} jagten sie ohne Gnade, vertrieben sie aus ihren alten Landen und zerstreuten ihre Stämme. {link:cairne-bloodhoof}Cairne{/link} von den {link:bloodhoof-village}Bloodhoof{/link} nahm es auf sich, sein Volk zu sammeln und es in ein Land zu führen, wo es in Sicherheit leben konnte.]=],
		},
		{
			title = "Die Gegenwart",
			text = [=[Die {link:centaurs}Zentauren{/link} wurden vertrieben, doch Mulgore kommt nicht zur Ruhe. Die {link:bristleback-quilboar}Stacheleber der Borstennacken{/link} führen Krieg gegen die jungen {link:tauren}Tauren{/link} von {link:red-cloud-mesa}Red Cloud Mesa{/link} und schänden die Begräbnisstätte der {link:red-rocks}Teufelsfelsen{/link}. {link:palemane-gnolls}Gnolle der Bleichmähnen{/link} jagen das Wild bis zum Verderben und beantworten jedes Wort des Friedens mit Klingen. {link:windfury-harpies}Harpyien der Windfurien{/link} nisten auf den Graten. Die Goblins der {link:venture-company}Venture Co.{/link} haben die heiligen Brunnen vergiftet und eine Mine in die östlichen Klippen gegraben, und {link:dwarves}Zwerge{/link} graben im Westen nach alten Geheimnissen. In diesen Tagen wurde erneut eine Schar Zentauren der Galak innerhalb der Grenzen gesehen, und eine {link:longwalkers}Langwanderin{/link}, die ausgesandt wurde, um den Osten zu beobachten, kam nicht nach Hause. Im Nordwesten haben die Schamanen des {link:earthen-ring}Irdenen Rings{/link} ein Lager errichtet, wo ein seltsames Volk vom Himmel herabkommt: {link:skyborne}Skyborne{/link}-Elfen der {link:windshapers}Windshapers{/link}, herabgestiegen von {link:skywall}Skywall{/link}, um neue Verbündete zu suchen.]=],
		},
		{
			title = "Bewohner",
			text = [=[• {b}Die {link:tauren}Tauren{/link}.{/b} Jäger, Schamanen, Druiden und Tapfere leben in {link:camp-narache}Camp Narache{/link}, in {link:bloodhoof-village}Bloodhoof{/link} und in der Stadt darüber. Häuptling {link:baine-bloodhoof}Baine Bloodhoof{/link}, Sohn von {link:cairne-bloodhoof}Cairne{/link}, führt das Dorf an.
• {b}Der Irdene Ring.{/b} Schamanen verschiedener Völker versammeln sich unter {link:muln-earthfury}Muln Earthfury{/link} in {link:camp-gev-rek}Camp Gev'rek{/link}.
• {b}{link:bristleback-quilboar}Stacheleber der Borstennacken{/link}.{/b} Sie halten die {link:brambleblade-ravine}Dornrankenklamm{/link} und überfallen den Tafelberg und die Ebenen.
• {b}{link:palemane-gnolls}Gnolle der Bleichmähnen{/link}.{/b} Sie hausen im {link:palemane-rock}Bleichmähnenfels{/link} und in {link:camping}Lagern{/link} entlang der südlichen Hügel.
• {b}{link:windfury-harpies}Harpyien der Windfurien{/link}.{/b} Sie nisten an den Bergrändern im Südosten und auf dem {link:windfury-ridge}Windfurienkamm{/link}.
• {b}Die {link:venture-company}Venture Co.{/link}{/b} Goblinbergleute, Holzfäller und Aufseher, die das Land von seinem Volk leeren wollen.]=],
		},
		{
			title = "Geschichte",
			text = [=[• {b}Der lange Marsch.{/b} Nahe den Küsten des Großen Meeres stieß der junge Kriegshäuptling {link:thrall}Thrall{/link} auf Cairnes Volk, das von {link:centaurs}Zentauren{/link} angegriffen wurde. Die {link:orcs}Orcs{/link} geleiteten die Karawanen der {link:tauren}Tauren{/link} durch das {link:the-barrens}Brachland{/link} nach Mulgore, und im Gegenzug zeigte {link:cairne-bloodhoof}Cairne{/link} Thrall den Weg zum Orakel im {link:stonetalon-mountains}Steinkrallengebirge{/link}.
• {b}Der Dritte Krieg.{/b} Cairne verpflichtete sein Volk der {link:horde}Horde{/link}, und Taurenkrieger kämpften an der Seite der Orcs in der {link:battle-of-mount-hyjal}Schlacht um den Berg Hyjal{/link}.
• {b}Die Inbesitznahme von Mulgore.{/b} Mit der Hilfe der Horde brachen die Tauren den Griff der Zentauren um die Ebenen und machten Mulgore zur dauerhaften Heimat all ihrer Stämme. Auf den Tafelbergen errichteten sie {link:thunder-bluff}Thunder Bluff{/link}.]=],
		},
		{
			title = "Kunde der Ebenen",
			text = [=[• Ein junger {link:tauren}Tauren{/link} verdient sich einen Platz in {link:thunder-bluff}Thunder Bluff{/link} durch die {link:rites-of-the-earthmother}Riten der Erdenmutter{/link}, die von {link:camp-narache}Camp Narache{/link} bis zur Halle des Hochhäuptlings führen.
• In den südöstlichen Hügeln, oberhalb des Tafelbergs, steht ein Schrein für An'she und Mu'sha, die Sonne und den Mond. Die Tauren ehren die Zwillinge, weil ihr Licht Leben und Führung schenkt, auch wenn sie nicht so zur Welt gehören wie die {link:elements}Elemente{/link}.
• Westlich des Stonebullsees schleicht ein Präriewolf, den die Jäger Chakuyak nennen, von einem Baumhain zum nächsten.]=],
		},
	},
})

Translate("deDE", "red-cloud-mesa", {
	title = "Red Cloud Mesa",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Red Cloud Mesa ist das Hochplateau im Süden von {link:mulgore}Mulgore{/link}, wo junge {link:tauren}Tauren{/link} ihre ersten Schritte als Jäger tun. Ebenenschreiter und Berglöwen streifen durch sein Gras, und die Ältesten sagen, sein Volk sei vor allem stolz auf seine scharfe Jagdkunst. Südöstlich des Lagers liegt ein Brunnen, an dem die Großmutter der Hawkwinds Wasser schöpft. In den Hügeln im Süden hat der {link:seer-graytongue}Seher Graytongue{/link} seine Behausung, und über den fernen südöstlichen Hängen steht ein Schrein für An'she und Mu'sha. Östlich des Tafelbergs öffnet sich die {link:brambleblade-ravine}Dornrankenklamm{/link}, aus der die {link:bristleback-quilboar}Stacheleber der Borstennacken{/link} bei Nacht kommen, um Jägern aufzulauern und aus dem Lager zu stehlen.]=],
		},
	},
})

Translate("deDE", "camp-narache", {
	title = "Camp Narache",
	aliases = { "Narache" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Camp Narache ist das Lager von {link:chief-hawkwind}Häuptling Hawkwind{/link} auf {link:red-cloud-mesa}Red Cloud Mesa{/link}. Es ist ein Ort der Zelte, Totems und Kochfeuer, und hier beginnen die Jungen des Stammes die {link:rites-of-the-earthmother}Riten der Erdenmutter{/link}. Der Häuptling lehrt, dass jedes Mitglied des Stammes einen Platz im Gleichgewicht der lebenden Dinge hat und dass die Ältesten selbst demütige Arbeit bemerken. Sein Sohn {link:grull-hawkwind}Grull{/link} prüft die jungen Jäger. Das Lager lebt unter Bedrohung, denn der Kriegshäuptling der {link:bristleback-quilboar}Borstennacken{/link} hat Pläne entworfen, es zu belagern. Wer sich hier bewährt, folgt der Straße nach Norden nach {link:bloodhoof-village}Bloodhoof{/link}.]=],
		},
	},
})

Translate("deDE", "brambleblade-ravine", {
	title = "Dornrankenklamm",
	aliases = { "Dornranken" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Dornrankenklamm schneidet sich östlich von {link:red-cloud-mesa}Red Cloud Mesa{/link} in {link:razorfen-downs}die Hügel{/link}. Sie ist von Dornen überwuchert, und in ihr haben die {link:bristleback-quilboar}Stacheleber der Borstennacken{/link} ein grobes Dorf errichtet. Von hier schleichen ihre Plünderer auf den Tafelberg, um den Jagdgruppen von {link:camp-narache}Camp Narache{/link} aufzulauern. Die {link:quilboar}Stacheleber{/link} richten in der Klamm Kampfeber ab und lehren sie Bösartigkeit. Ihr Häuptling, {link:chief-sharptusk-thornmantle}Sharptusk Thornmantle{/link}, hat seine Hütte im Herzen der Klamm, und die {link:tauren}Tauren{/link} von Narache sagen, dass sein Krieg gegen sie viele Leben gekostet hat, seit sie in dieses Land kamen.]=],
		},
	},
})

Translate("deDE", "bloodhoof-village", {
	title = "Bloodhoof",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Bloodhoof liegt im Herzen von {link:mulgore}Mulgore{/link}, an der Straße zwischen {link:red-cloud-mesa}Red Cloud Mesa{/link} und {link:thunder-bluff}Thunder Bluff{/link}. Es ist das Dorf von Cairnes eigenem Stamm, und sein Sohn {link:baine-bloodhoof}Baine{/link} führt es als Häuptling an. Um sein großes Feuer versammeln sich die Lehrer des Stammes: der Schamane {link:mull-thunderhorn}Mull Thunderhorn{/link}, der die vergifteten Brunnen reinigt, der geistige Führer {link:zarlman-two-moons}Zarlman Two-Moons{/link}, der Krieger {link:ruul-eagletalon}Ruul Eagletalon{/link} und die Jäger {link:harken-windtotem}Harken Windtotem{/link} und {link:skorn-whitecloud}Skorn Whitecloud{/link}. Sein Gasthaus heißt Reisende willkommen. Von Bloodhoof aus ziehen die jungen {link:tauren}Tauren{/link} zu den Brunnen, zur Mine und zu den Gnolllagern, und wer den Ritus der Vision besteht, bricht von hier zur Stadt auf.]=],
		},
	},
})

Translate("deDE", "water-wells-of-mulgore", {
	title = "Wasserbrunnen von Mulgore",
	aliases = { "Wasserbrunnen von Winterhoof", "Wasserbrunnen von Thunderhorn", "Wasserbrunnen von Wildmane", "Brunnen von Mulgore" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Drei heilige Brunnen tränken {link:mulgore}die Ebenen von Mulgore{/link}, jeder nach einem Taurenclan benannt. Der Wasserbrunnen von Winterhoof liegt südöstlich von {link:bloodhoof-village}Bloodhoof{/link}, der Wasserbrunnen von Thunderhorn nördlich davon und der Wasserbrunnen von Wildmane nördlich von {link:thunder-bluff}Thunder Bluff{/link}. Die Brunnen schenken den {link:tauren}Tauren{/link} Leben und ebenso den Tieren, von denen sie abhängen. Die Goblins der {link:venture-company}Venture Co.{/link} und ihre Diener haben alle drei verunreinigt. Um sie zu reinigen, fertigt der Schamane {link:mull-thunderhorn}Mull Thunderhorn{/link} für jeden ein Totem aus dem, was das Land selbst bietet, und am Brunnen muss dann ein Ritual vollzogen werden, oft unter den Augen goblinischer Wachen.]=],
		},
	},
})

Translate("deDE", "the-venture-co-mine", {
	title = "Die Mine der Venture Co.",
	aliases = { "Mine der Venture Co." },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Mine der Venture Co. ist in die östlichen Klippen von {link:mulgore}Mulgore{/link} gehauen, nordöstlich des Stonebullsees. Hier graben die Goblins der {link:venture-company}Venture Co.{/link} ohne Erlaubnis Erz und Mineralien aus Taurenland. Ihr Vorarbeiter, {link:supervisor-fizsprocket}Fizsprocket{/link}, verwahrte Pläne, die {link:tauren}Tauren{/link} ganz aus Mulgore zu vertreiben, damit die Gesellschaft die Ebenen nach Belieben ausplündern könnte. Seine Notizen sprechen auch von Schreddern, großen Maschinen, die einen Wald in Tagen fällen können, und von den Plänen der Gesellschaft, sich weiter über das Land auszubreiten.]=],
		},
	},
})

Translate("deDE", "ravaged-caravan", {
	title = "Überfallene Karawane",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Überfallene Karawane liegt am Nordufer des Stonebullsees. Sie war ein Zug der {link:venture-company}Venture Co.{/link}, der unter Bewachung reiste, und die {link:tauren}Tauren{/link}, die in einem früheren Kampf zwei der Ihren an die Goblins verloren hatten, fielen über ihn her und verbrannten ihn. Die Vorratskisten ließen sie zurück, in dem Glauben, das Feuer habe sie verdorben. Das hatte es nicht. Die Kisten enthielten Erz aus {link:mulgore}Mulgore{/link} und einen Stapel Papiere, die das Ausmaß des Bergbaus der Gesellschaft in den Landen der Tauren enthüllten.]=],
		},
	},
})

Translate("deDE", "palemane-rock", {
	title = "Bleichmähnenfels",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Bleichmähnenfels ist eine Höhle in den westlichen Hügeln von {link:mulgore}Mulgore{/link}, der Unterschlupf der {link:palemane-gnolls}Gnolle der Bleichmähnen{/link}. Von hier ziehen die {link:gnolls}Gnolle{/link} aus, um die Herden zu wildern, ihre Beute zu häuten und die Felle zu gerben, und sie nehmen weit mehr, als das Land geben kann. Die {link:tauren}Tauren{/link} versuchten, mit ihnen zu sprechen, und stießen auf Verachtung. In diesen Tagen sandte der Hochhäuptling einen {link:longwalkers}Langwanderer{/link}, {link:perith-stormhoof}Perith Stormhoof{/link}, um es noch einmal zu versuchen. Die Gnolle antworteten mit Gewalt, und Perith wurde im Fels festgehalten, in der Furcht, zu ihrem Festmahl zu werden.]=],
		},
	},
})

Translate("deDE", "bael-dun-digsite", {
	title = "Grabungsstätte von Bael'dun",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Grabungsstätte von Bael'dun liegt im Westen von {link:mulgore}Mulgore{/link}, nordwestlich von {link:bloodhoof-village}Bloodhoof{/link}. {link:dwarves}Zwerge{/link} haben hier ein Lager errichtet und graben in die Erde, mit Grabenden, die den Boden aufbrechen, und Schätzern, die beurteilen, was sie finden. Sie glauben, dass in Mulgore Geheimnisse begraben liegen. Häuptling {link:baine-bloodhoof}Baine Bloodhoof{/link} bezweifelt das nicht. Er hält nur daran fest, dass das Aufreißen und Beschmutzen der Erde der falsche Weg ist, ihre Geheimnisse zu erfahren, und er hat darum gebeten, die Grabwerkzeuge der Zwerge an sich zu nehmen und zu zerschlagen.]=],
		},
	},
})

Translate("deDE", "red-rocks", {
	title = "Teufelsfelsen",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Teufelsfelsen sind die heilige Begräbnisstätte der {link:tauren}Tauren{/link}, im Nordosten von {link:mulgore}Mulgore{/link} jenseits von {link:thunder-bluff}Thunder Bluff{/link}. Nur die Tapfersten werden hier zur Ruhe gebettet: die Krieger, die halfen, die Stadt zu gründen und zu verteidigen, und jene, die ihr Leben für ihre Stämme und Häuptlinge gaben. Ahnengeister wohnen zwischen den Steinen, und hierher kommen junge Tauren, die vom Wasser der Seher getrunken haben, um den Segen ihrer Vorfahren zu empfangen. Der alte {link:lorekeeper-raintotem}Überlieferungshüter Raintotem{/link} wacht über die Gräber. Plünderer der {link:bristleback-quilboar}Borstennacken{/link} sind in letzter Zeit auf den heiligen Boden gekommen, um ihn zu verwüsten.]=],
		},
	},
})

Translate("deDE", "windfury-ridge", {
	title = "Windfurienkamm",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Windfurienkamm ist der hohe Nordrand von {link:mulgore}Mulgore{/link}, wo die Ebenen zu den Bergen ansteigen. Er ist die Festung der {link:windfury-harpies}Harpyien der Windfurien{/link}. Ihre Matriarchinnen und Zauberinnen nisten zwischen den Felsen, und ihre Hexen rufen den Wind. Die {link:tauren}Tauren{/link} zählen die {link:harpies}Harpyien{/link} zu den natürlichen Feinden Mulgores, doch sie schätzen auch die azurblauen und bronzenen Federn der nördlichen Schwärme für den Kopfschmuck, der vor dem Hochhäuptling getragen wird. Die Harpyie Schwester Hatelash soll die Schwärme des Nordwestens anführen.]=],
		},
	},
})

Translate("deDE", "the-golden-plains", {
	title = "Die goldenen Ebenen",
	aliases = { "Goldene Ebenen" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die goldenen Ebenen erstrecken sich östlich von {link:thunder-bluff}Thunder Bluff{/link}, ein Meer aus hohem Gras zwischen der Stadt und den östlichen Klippen. Flachlandpumas jagen hier, und der alte Schreiter {link:mazzranache}Mazzranache{/link} soll durch dasselbe Land streifen. Hin und wieder durchquert ein großer weißer Wolf namens {link:ghost-howl}Ghost Howl{/link} diese Ebenen, sein Fell noch vernarbt vom Kampf gegen Dämonen. Die Goblins der {link:venture-company}Venture Co.{/link} schlagen ihre Wege durch das Gras zwischen ihrer Mine und den Brunnen. In diesen Tagen wurde einer ihrer Schredder auf den Ebenen gesehen, eine Maschine, die die {link:tauren}Tauren{/link} keinen einzigen Baum Mulgores fällen lassen werden.]=],
		},
	},
})

Translate("deDE", "camp-gev-rek", {
	title = "Camp Gev'rek",
	aliases = { "Skywatcher Plateau" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Camp Gev'rek steht auf dem Skywatcher Plateau im Nordwesten von {link:mulgore}Mulgore{/link}. Es ist eine Versammlung des {link:earthen-ring}Irdenen Rings{/link}: Taurenschamanen, ein Troll, sogar einer der Grimmtotem, angeführt von {link:muln-earthfury}Muln Earthfury{/link} und der ältesten Weitseherin Nuara Tremorhoof. Hier kommen die Himmelsschneider-Schiffe der {link:windshapers}Windshapers{/link} von {link:zephras-isle}Zephras Isle{/link} herab und bringen {link:skyborne}Skyborne{/link}-Elfen in eine Welt, die sie nie gesehen haben. {link:alaana-stormwalker}Alaana Stormwalker{/link} begrüßt jeden Neuankömmling. Neben dem Lager haben ein Goblinhändler, eine Priesterin von An'she und Betreuer der Sturmschreiter der Skyborne ihre Stände aufgebaut.]=],
		},
	},
})

