})

Translate("deDE", "grull-hawkwind", {
	title = "Grull Hawkwind",
	subtitle = "Jäger von Red Cloud Mesa",
	found = "Camp Narache, auf Red Cloud Mesa",
	hint = [=[Findet den Sohn des Häuptlings, der die jungen Jäger von Narache prüft.]=],
	allegiance = "Tauren · Camp Narache",
	aliases = { "Grull" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Grull Hawkwind ist der Sohn von {link:chief-hawkwind}Häuptling Hawkwind{/link} und ein Jäger von {link:red-cloud-mesa}Red Cloud Mesa{/link}. Er prüft die Jungen, die in {link:camp-narache}Camp Narache{/link} ankommen, bevor sie vor seinen Vater treten. Er lehrt, dass die {link:tauren}Tauren{/link} aus Notwendigkeit ebenso jagen wie zum Sport und dass ein Tier genommen wird, um den Stamm zu ernähren und zu kleiden, niemals als bloße Trophäe.]=],
		},
		{
			title = "Bedeutung",
