Translate("deDE", "baine-bloodhoof", {
	title = "Baine Bloodhoof",
	subtitle = "Häuptling von Bloodhoof",
	found = "Die Mitte von Bloodhoof",
	hint = [=[Sucht den Sohn des Hochhäuptlings auf, der Bloodhoof anführt.]=],
	allegiance = "Tauren · Stamm der Bloodhoof · Horde",
	aliases = { "Baine" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Baine Bloodhoof ist der Sohn von {link:cairne-bloodhoof}Cairne Bloodhoof{/link} und der Häuptling von {link:bloodhoof-village}Bloodhoof{/link}. Er herrscht über das Herz von {link:mulgore}Mulgore{/link}, während sein Vater von {link:thunder-bluff}Thunder Bluff{/link} aus herrscht. Er ist geduldig mit jenen, die das Land teilen wollen, und streng mit jenen, die es nicht wollen. Er hat viele der Konflikte gesehen, die die Welt verwunden, und er hofft, dass die Jungen seines Stammes weniger davon sehen werden.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Baine ist die nächste Generation der {link:bloodhoof-village}Bloodhoof{/link}. Die Jungen, die durch sein Dorf ziehen, lernen von ihm, was es heißt, die Heimat der {link:tauren}Tauren{/link} zu verteidigen.]=],
		},
		{
			title = "Taten",
			text = [=[• Er setzt die {link:rites-of-the-earthmother}Riten der Erdenmutter{/link} fort und schickt die Jungen zum geistigen Führer {link:zarlman-two-moons}Zarlman Two-Moons{/link} für den Ritus der Vision.
• Er befahl, die {link:palemane-gnolls}Gnolle der Bleichmähnen{/link} zurückzudrängen, als sie jeden Versuch des Friedens zurückwiesen.
• Er befahl, die Werkzeuge der zwergischen Gräber zu zerstören.
• Er ruft bisweilen die {link:longwalkers}Langwanderer{/link}, die Späher seines Vaters, um Hilfe an.
• Er führte in diesen Tagen die Verteidigung gegen einen Raubtrupp der Galak.]=],
		},
	},
	chapters = {
		{
			title = "Das Land teilen",
			hint = [=[Erfahrt das Urteil des Häuptlings über die Gnolle von Mulgore.]=],
			text = [=[Die {link:palemane-gnolls}Gnolle der Bleichmähnen{/link} kamen nach {link:mulgore}Mulgore{/link} und erlegten sein Wild ohne Maß. Die {link:tauren}Tauren{/link} versuchten immer wieder, sie mit Worten zu erreichen. Baine kam schließlich zu dem Schluss, dass Worte nicht länger die Antwort waren. Er wollte den Jungen zeigen, wie furchtbar selbst eine kleine Bedrohung werden kann, wenn man sie unbeachtet lässt.]=],
		},
		{
			title = "Unser alter Feind",
			hint = [=[Kümmert Euch um die Zentauren, die nach Mulgore eingedrungen sind.]=],
			text = [=[Als ihn der Bericht der erschlagenen {link:longwalkers}Langwanderin{/link} Malah erreichte, las Baine ihn schweigend. Dann erklärte er, die {link:tauren}Tauren{/link} würden den {link:centaurs}Zentauren{/link} keinen einzigen Grashalm überlassen. Er schickte Krieger aus, um das Lager der Galak anzugreifen, bevor seine Reiter sein Dorf erreichen konnten, und bat darum, den Kopf ihres Anführers als Warnung für andere zurückzubringen.]=],
		},
		{
			title = "Der gefangene Sohn",
			hint = [=[Erfahrt von den Tagen, als Baine von den Zentauren verschleppt wurde.]=],
			text = [=[In den Monaten, nachdem sich die {link:tauren}Tauren{/link} in {link:mulgore}Mulgore{/link} niedergelassen hatten, ergriffen {link:centaurs}Zentauren{/link} Baine. Sein Vater verfiel in eine so tiefe Verzweiflung, dass er nicht mehr führen wollte. Es waren der {link:orcs}Orc{/link} {link:rexxar}Rexxar{/link} und der Tauren Bovan Windtotem, die Baine fanden und nach Hause brachten. Wenn Baine die Jungen nun zu seinem Vater schickt, spricht er voller Stolz von dem Tag, an dem {link:cairne-bloodhoof}Cairne{/link} mit {link:thrall}Thrall{/link} ritt, um diese Ebenen zurückzuerobern.]=],
		},
	},
	mentions = {
		{
			text = [=[{link:rites-of-the-earthmother}Riten der Erdenmutter{/link}, überbracht von {link:chief-hawkwind}Häuptling Hawkwind{/link}]=],
		},
		{ text = "Ritus der Vision" },
		{ text = "Zwergische Grabungen" },
		{ text = "Unser alter Feind, der Bericht, den er erhielt" },
		{ text = "Der Hochhäuptling" },
	},
	bonds = {
		{ id = "cairne-bloodhoof", name = "Cairne Bloodhoof", note = "sein Vater" },
		{ id = "chief-hawkwind", name = "Häuptling Hawkwind", note = "schickt ihm die Jungen" },
		{ id = "zarlman-two-moons", name = "Zarlman Two-Moons", note = "geistiger Führer seines Dorfes" },
		{ id = "brave-wildrunner", name = "Tapferer Wildrunner", note = "ein Tapferer seines Dorfes" },
		{ id = "herak-the-pillager", name = "Herak der Plünderer", note = "Feind" },
	},
})

Translate("deDE", "harken-windtotem", {
