			text = [=[Skorn Whitecloud ist ein alter Jäger aus {link:bloodhoof-village}Bloodhoof{/link}. Einst verspürte er dieselbe Wanderlust, die er in den Jungen sieht, und er hält die Jagd für die größte Ehre eines {link:tauren}Tauren{/link}. Wer den Pfad des Jägers gehen will, den schickt er zu {link:melor-stonehoof}Melor Stonehoof{/link} in {link:thunder-bluff}Thunder Bluff{/link}, mit den Klauen der Flachlandstreuner von {link:mulgore}Mulgore{/link}, zäher und listiger Beute, die eines jungen Jägers würdig ist.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Skorn bewahrt die Kunde der großen Jagden von {link:mulgore}Mulgore{/link}, darunter die Geschichte von {link:ghost-howl}Ghost Howl{/link}, dem vernarbten weißen Wolf.]=],
		},
		{
			title = "Taten",
			text = [=[• Er schickt junge Jäger mit den Klauen von Flachlandstreunern zur {link:hunter-rise}Anhöhe der Jäger{/link}.
• Er erfährt vom Tod von {link:ghost-howl}Ghost Howl{/link}.]=],
		},
	},
	mentions = {
		{ text = "Der Weg des Jägers" },
		{ text = "Der dämonenvernarbte Umhang" },
	},
	bonds = {
		{ id = "melor-stonehoof", name = "Melor Stonehoof", note = "der Jäger, zu dem er die Jungen schickt" },
		{ id = "ghost-howl", name = "Ghost Howl", note = "der Wolf seiner Geschichten" },
	},
})

Translate("deDE", "lorekeeper-raintotem", {
	title = "Überlieferungshüter Raintotem",
	subtitle = "Hüter der Teufelsfelsen",
	found = "Teufelsfelsen",
	hint = [=[Sucht den alten Überlieferungshüter an der heiligen Begräbnisstätte.]=],
	allegiance = "Tauren",
	aliases = { "Raintotem" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Überlieferungshüter Raintotem wacht über die {link:red-rocks}Teufelsfelsen{/link}, die heilige Begräbnisstätte der {link:tauren}Tauren{/link}. Er kennt die Namen der Tapferen, die dort liegen, der Gründer und Verteidiger von {link:thunder-bluff}Thunder Bluff{/link}. In den Teufelsfelsen begraben zu werden, ist die größte Ehre, die die Stämme vergeben können. Er ist nun alt und hat seine besten Jahre hinter sich, und als Plünderer der {link:bristleback-quilboar}Borstennacken{/link} kamen, um die Gräber zu verwüsten, konnte er sie nicht selbst vertreiben.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Raintotem hütet das Andenken der toten {link:tauren}Tauren{/link}, und er ruft die Lebenden auf, es zu verteidigen. Die Plünderer zwischen den Gräbern zu lassen, würde die Helden entehren, die die Heimat der Tauren erbauten.]=],
		},
		{
			title = "Taten",
			text = [=[• Er bittet darum, die {link:quilboar}Stacheleber{/link} vom heiligen Boden zu vertreiben.]=],
		},
	},
	mentions = {
		{ text = "Ein heiliges Begräbnis" },
	},
	bonds = {
		{ id = "chief-sharptusk-thornmantle", name = "Häuptling Sharptusk Thornmantle", note = "Häuptling des Stammes der Plünderer" },
	},
})

Translate("deDE", "brave-wildrunner", {
	title = "Tapferer Wildrunner",
	subtitle = "Tapferer von Bloodhoof",
	found = "Bloodhoof",
	hint = "Sprecht mit dem Tapferen, der über Bloodhoof Wache hält.",
	allegiance = "Tauren · Bloodhoof",
	aliases = { "Wildrunner" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Tapferer Wildrunner bewacht {link:bloodhoof-village}Bloodhoof{/link}. Als die {link:longwalkers}Langwanderin{/link} Malah Longwind nach drei Tagen nicht von der Ostgrenze zurückkehrte, fiel es ihm zu, herauszufinden, was geschehen war. Seine Pflicht hielt ihn im Dorf, also schickte er einen anderen an seiner Stelle. Die Nachricht, die zurückkam, war die schlimmste, die er hätte hören können. Malah war tot aufgefunden worden, nahe dem östlichen Rand von {link:mulgore}Mulgore{/link}, mit Zentaurenpfeilen im Rücken und ihrem Bericht noch in der Hand.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Wildrunners Wachsamkeit gab dem Dorf die Warnung vor dem Überfall der Galak.]=],
		},
		{
			title = "Taten",
			text = [=[• Er schickte einen Suchenden nach der vermissten {link:longwalkers}Langwanderin{/link} aus.
• Er brachte ihren Bericht zu Häuptling {link:baine-bloodhoof}Baine Bloodhoof{/link}.]=],
		},
	},
	mentions = {
		{ text = "{link:longwalkers}Langwanderin{/link} Malah" },
		{ text = "Düstere Kunde" },
		{ text = "Unser alter Feind" },
	},
	bonds = {
		{ id = "baine-bloodhoof", name = "Baine Bloodhoof", note = "sein Häuptling" },
	},
})

Translate("deDE", "perith-stormhoof", {
	title = "Perith Stormhoof",
	subtitle = "Langwanderer des Hochhäuptlings",
	found = "Im Bleichmähnenfels",
	hint = [=[Sucht nach dem Tauren, der in der Höhle der Gnolle gefangen gehalten wird.]=],
	allegiance = "Langwanderer · Hochhäuptling Cairne Bloodhoof",
	aliases = { "Perith" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Perith Stormhoof ist ein {link:longwalkers}Langwanderer{/link}, einer der vertrauten Späher des Hochhäuptlings. {link:cairne-bloodhoof}Cairne{/link} schickte ihn zum {link:palemane-rock}Bleichmähnenfels{/link}, um mit den Gnollen zu sprechen, die sich dort niedergelassen hatten. Die {link:gnolls}Gnolle{/link} begegneten seinen Worten mit Gewalt und hielten ihn in ihrer Höhle fest. Den Rest seines Auftrags hält er geheim, wie es alle Langwanderer müssen.]=],
		},
		{
			title = "Bedeutung",
			text = [=[{link:cairne-bloodhoof}Cairne{/link} nennt Perith seinen vertrautesten Späher und sagt, seine Mission sei von höchster Wichtigkeit.]=],
		},
		{
			title = "Taten",
			text = [=[• Er versuchte im Auftrag Cairnes mit den Gnollen der {link:palemane-gnolls}Bleichmähnen{/link} zu verhandeln.
• Er entkam dem {link:palemane-rock}Bleichmähnenfels{/link} und setzte seine Aufgabe allein fort.]=],
		},
	},
	chapters = {
		{
			title = "Die Flucht des Langwanderers",
			hint = "Helft dem gefangenen Langwanderer aus dem Bleichmähnenfels.",
			text = [=[Einmal aus der Höhle befreit, ruhte Perith in der Wärme von An'she und versorgte seine Wunden. Dann ging er allein weiter und schwor, {link:cairne-bloodhoof}Cairne{/link} nicht zu enttäuschen. Er bat nur darum, dass Nachricht von seiner Sicherheit nach {link:thunder-bluff}Thunder Bluff{/link} gebracht werde.]=],
		},
	},
	mentions = {
		{ text = "Die {link:longwalkers}Langwanderer{/link}" },
	},
	bonds = {
		{ id = "cairne-bloodhoof", name = "Cairne Bloodhoof", note = "sein Häuptling" },
	},
})

Translate("deDE", "alaana-stormwalker", {
	title = "Alaana Stormwalker",
	subtitle = "Windshaper von Camp Gev'rek",
	found = "Camp Gev'rek, auf dem Skywatcher Plateau",
	hint = [=[Begrüßt die Skyborne, die Reisende von Zephras Isle empfängt.]=],
	allegiance = "Windshapers · Horde",
	aliases = { "Alaana" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Alaana Stormwalker ist eine {link:skyborne}Skyborne{/link} der {link:windshapers}Windshapers{/link}, die vor den meisten ihres Volkes nach {link:mulgore}Mulgore{/link} herabkam. Sie wartet in {link:camp-gev-rek}Camp Gev'rek{/link}, um jeden Himmelsschneider von {link:zephras-isle}Zephras Isle{/link} zu empfangen. Sie heißt die Neuankömmlinge freudig willkommen, warnt sie, dass die Welt unten ebenso gefährlich wie wundersam ist, und sagt ihnen, dass ihre neuen Verbündeten der Schlüssel zum Überleben ihres Volkes sind.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Für die {link:windshapers}Windshapers{/link} ist Alaana die erste Stimme von {link:azeroth}Azeroth{/link}. Sie erklärt ihnen die {link:horde}Horde{/link} und schickt sie weiter zu deren Kriegshäuptling.]=],
		},
		{
			title = "Taten",
			text = [=[• Sie empfängt die Vorhut der {link:windshapers}Windshapers{/link} in {link:mulgore}Mulgore{/link}.
• Sie schickt jeden Neuankömmling zu {link:thrall}Thrall{/link} nach {link:orgrimmar}Orgrimmar{/link}, um im Namen der Windshapers zu sprechen.]=],
		},
	},
	mentions = {
		{ text = "Der Irdene Ring" },
		{ text = "Willkommen in {link:azeroth}Azeroth{/link}" },
	},
	bonds = {
		{ id = "muln-earthfury", name = "Muln Earthfury", note = "Gastgeber der Windshapers" },
		{ id = "thrall", name = "Thrall", note = "der Kriegshäuptling, zu dem sie sie schickt" },
	},
})

Translate("deDE", "muln-earthfury", {
	title = "Muln Earthfury",
	subtitle = "Ältester des Irdenen Rings",
	found = "Camp Gev'rek, auf dem Skywatcher Plateau",
	hint = [=[Sucht den ältesten Schamanen, der die Skyborne in Mulgore willkommen heißt.]=],
	allegiance = "Irdener Ring · Tauren",
	aliases = { "Muln" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Muln Earthfury ist ein Taurenschamane und ein Anführer des {link:earthen-ring}Irdenen Rings{/link}, des Rates, der das Gleichgewicht der {link:elements}Elemente{/link} wahrt. In diesen Tagen führte ihn seine Pflicht gegenüber den Geistern über die Welt selbst hinaus, nach {link:skywall}Skywall{/link}, dem Reich der Luft. Dort folgte er dem Ruf der {link:windshapers}Windshapers{/link}, und als er zurückkehrte, brachte er sie mit.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Muln ist die Brücke zwischen den {link:skyborne}Skyborne{/link} und {link:azeroth}Azeroth{/link}. Durch ihn fanden die {link:windshapers}Windshapers{/link} den Irdenen Ring, und durch den Ring fanden sie die {link:horde}Horde{/link}. Die Elfen, die nach {link:mulgore}Mulgore{/link} herabkommen, sind seine Gäste, und sie lernen die Welt zuerst durch sein Lager und seinen Rat kennen.]=],
		},
		{
			title = "Taten",
			text = [=[• Er folgte dem Hilferuf der Anführerin der {link:windshapers}Windshapers{/link}, {link:ayessa-dawnsinger}Ayessa Dawnsinger{/link}, deren Heimat im Niedergang war.
• Er zog mit Schamanen des Irdenen Rings nach {link:zephras-isle}Zephras Isle{/link}, um den {link:skyborne}Skyborne{/link} beizustehen.
• Er trat einem der großen Herren des Windes entgegen und sagte ihm, dass der Ring keinen Streit mit ihm habe.
• Er warnte die Windshapers vor den Elementarfürsten und vor gutem Grund, {link:al-akir}Al'Akir{/link} zu fürchten.
• Er eröffnete einen Weg der Himmelsschneider-Schiffe zwischen Zephras Isle und {link:mulgore}Mulgore{/link}.
• Er unterhält das Lager auf dem {link:camp-gev-rek}Skywatcher Plateau{/link}, wo die Neuankömmlinge eintreffen.]=],
		},
		{
			title = "Unverzeichnet",
			text = [=[Wenig ist über Mulns Leben vor diesen Tagen geschrieben. Die Chroniken dieses Zeitalters verzeichnen nicht, wann er zur Führung des Rings aufstieg oder wie {link:ayessa-dawnsinger}Ayessa{/link} ihn zuerst über die Ebenen hinweg erreichte.]=],
		},
	},
	chapters = {
		{
			title = "Hilfe von unten",
			hint = [=[Steht den Windshapers in ihrer dunkelsten Stunde auf Zephras Isle bei.]=],
			text = [=[Die {link:windshapers}Windshapers{/link} hatten um Hilfe geschickt, und sie kam nur langsam. Als Muln und die Schamanen des Irdenen Rings endlich eintrafen, tobte die Schlacht gegen den Kult der {link:high-priestess-lorthuna}Hohepriesterin Lorthuna{/link} bereits. Er bat {link:ayessa-dawnsinger}Ayessa{/link} um Verzeihung für sein spätes Kommen. Als der Herr des Ostwinds über sie kam, sprach Muln für den Ring: Sie hätten keinen Streit mit ihm und bäten nur darum, in Frieden gelassen zu werden. Als die Schlacht vorüber war, kehrte er sogleich nach {link:azeroth}Azeroth{/link} zurück.]=],
		},
		{
			title = "Die Warnung",
			hint = [=[Erfahrt, was der Irdene Ring den Windshapers über den Windfürsten erzählte.]=],
			text = [=[Muln erzählte {link:ayessa-dawnsinger}Ayessa{/link} viel über die Elementarfürsten. Was er ihr sagte, ließ sie in Furcht zurück. Die Schutzbanne, die {link:zephras-isle}Zephras Isle{/link} verborgen hatten, waren fort, und nichts stand mehr zwischen der Insel und {link:al-akir}Al'Akir{/link} in seinem eigenen Reich. Der Hohe Älteste der {link:skyborne}Skyborne{/link} sah es weitsichtiger: Für einen Elementarfürsten könnten Jahre oder sogar Jahrzehnte vergehen, bevor er seinen Blick auf sie richtete.]=],
		},
		{
			title = "Der Weg der Himmelsschneider",
			hint = [=[Nehmt ein Schiff von Zephras Isle in das Land des Irdenen Rings.]=],
			text = [=[Muln arbeitete hart daran, die Überfahrt sicher zu machen. Probefahrten segelten zwischen der Insel und {link:mulgore}Mulgore{/link}, wo der Irdene Ring seine Heimat hat, bis die Himmelsschneider regelmäßig verkehrten und die ersten {link:skyborne}Skyborne{/link} bereits auf der anderen Seite warteten.]=],
		},
	},
	mentions = {
		{ text = "Der Irdene Ring, sein Lager in {link:mulgore}Mulgore{/link}" },
		{ text = "Kind der Natur" },
		{ text = "Die {link:horde}Horde{/link} erkunden" },
	},
	bonds = {
		{ id = "alaana-stormwalker", name = "Alaana Stormwalker", note = "empfängt die Windshapers in seinem Lager" },
		{ id = "cairne-bloodhoof", name = "Cairne Bloodhoof", note = "Hochhäuptling seines Volkes" },
		{ id = "thrall", name = "Thrall", note = "Kriegshäuptling der Horde und ein Schamane" },
		{ id = "hamuul-runetotem", name = "Hamuul Runetotem", note = "vom Zirkel des Cenarius, der seine Gäste willkommen heißt" },
	},
})

Translate("deDE", "kaga-wildhoof", {
	title = "Kaga Wildhoof",
	subtitle = "Eine Reisende der Ebenen",
	found = "Ein Lagerfeuer südlich von Bloodhoof",
	hint = [=[Sucht die Tauren, die südlich von Bloodhoof ein Lagerfeuer und ein Zelt unterhält.]=],
	allegiance = "Umherziehende Abenteurerin",
	aliases = { "Kaga" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Kaga Wildhoof unterhält ein Lagerfeuer und ein Zelt neben der Straße südlich von {link:bloodhoof-village}Bloodhoof{/link}. Diese {link:tauren}Tauren{/link} der offenen Straße lehrt die Jungen die Kunst des {link:camping}Lagerns{/link}: ein Feuer zu entzünden, die Werke jedes Handwerks darum herum aufzustellen und daneben zu ruhen, bis sich seine Wohltat in den Knochen festsetzt.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Kaga ist der Ansicht, dass jedes Handwerk, selbst das des Fischers, einem Lager etwas zu geben hat. Unter dieser Lehre wird die alte Kunst der {link:tauren}Tauren{/link}, auf den Ebenen zu leben, zu einem Handwerk, das alle teilen.]=],
		},
		{
			title = "Taten",
			text = [=[• Lädt Reisende ein, sich ans Feuer zu setzen und zu lernen.
• Zeigt, wie das Zelt eines Lederverarbeiters einem Lager Erholung verschafft.]=],
		},
	},
	mentions = {
		{
			text = [=[Der Abenteurer, geschickt von {link:chief-hawkwind}Häuptling Hawkwind{/link}]=],
		},
		{ text = "Die große Wildnis" },
		{ text = "{link:camping}Lagern{/link} 101: Kochen" },
	},
	bonds = {
		{ id = "chief-hawkwind", name = "Häuptling Hawkwind", note = "schickt die Jungen zu Kaga" },
	},
})

