Translate("deDE", "mazzranache", {
	title = "Mazzranache",
	subtitle = "Der rotäugige Schreiter",
	found = "Streift durch die Ebenen östlich von Thunder Bluff",
	hint = [=[Stellt Euch dem alten Schreiter mit den brennend roten Augen.]=],
	allegiance = "Tiere von Mulgore",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Mazzranache ist ein Schreiter der Ebenen von {link:mulgore}Mulgore{/link}, von dem die Geschichten der Jäger von {link:bloodhoof-village}Bloodhoof{/link} erzählen. Er hat dämonische rote Augen, messerscharfe Klauen und einen giftigen Biss. {link:maur-raincaller}Maur{/link} Raincallers Großvater kämpfte vor langer Zeit gegen ihn, und nun trägt Maur selbst das Mal seines Bisses. Er streift durch die Ebenen östlich von {link:thunder-bluff}Thunder Bluff{/link} und ist nicht leicht zu finden.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Mazzranache ist einer der alten Schrecken der Ebenen. Um sein Gift aus einer Wunde zu ziehen, brauchen die Heiler von {link:bloodhoof-village}Bloodhoof{/link} das Herz eines Wolfes, den Oberschenkelknochen eines Pumas, die Schuppe eines Ebenenschreiters und den Muskelmagen eines Sturzfliegers.]=],
		},
		{
			title = "Taten",
			text = [=[• Er kämpfte in längst vergangenen Jahren gegen {link:maur-raincaller}Maur{/link} Raincallers Großvater.
• Er verwundete Maur Raincaller.]=],
		},
	},
	mentions = {
		{ text = "Mazzranache" },
	},
	bonds = {
		{ id = "maur-raincaller", name = "Maur Raincaller", note = "trägt seinen Biss" },
	},
})

Translate("deDE", "ghost-howl", {
	title = "Ghost Howl",
	subtitle = "Der vernarbte weiße Wolf",
	found = "Wandert über die Ebenen von Mulgore",
	hint = [=[Stellt Euch dem weißen Wolf, der über die Ebenen streift, vernarbt von alten Kämpfen.]=],
	allegiance = "Tiere von Mulgore",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Ghost Howl ist ein großer weißer Wolf, der über {link:mulgore}die Ebenen von Mulgore{/link} wandert. Sein zerzaustes Fell trägt eine schreckliche Wunde. Es heißt, er habe sie im Kampf gegen die {link:burning-legion}Brennende Legion{/link} empfangen, und sie hat ihn seither gezeichnet. Man sieht ihn bald unterhalb der Klippen von {link:thunder-bluff}Thunder Bluff{/link}, bald auf den östlichen Ebenen, bald weit im Norden.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Ghost Howl ist eine lebende Erinnerung an den Krieg gegen die Dämonen, getragen im Fell eines Tieres. Die Jäger von {link:bloodhoof-village}Bloodhoof{/link} bewahren seine Geschichte, und sie würden wissen wollen, wenn er fiele.]=],
		},
		{
			title = "Taten",
			text = [=[• Er kämpfte gegen die {link:burning-legion}Brennende Legion{/link} und überlebte.
• Er streift von einem Ende Mulgores zum anderen.]=],
		},
	},
	mentions = {
		{ text = "Der dämonenvernarbte Umhang" },
	},
	bonds = {
		{ id = "skorn-whitecloud", name = "Skorn Whitecloud", note = "kennt seine Geschichte" },
	},
})

Translate("deDE", "herak-the-pillager", {
	title = "Herak der Plünderer",
	subtitle = "Räuber der Galak",
	found = "Ein Zentaurenlager an der Ostgrenze von Mulgore",
	hint = [=[Stellt Euch dem Zentaurenräuber, der nach Mulgore eingedrungen ist.]=],
	allegiance = "Zentauren der Galak",
	aliases = { "Herak" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Herak der Plünderer führt einen kleinen Raubtrupp von {link:centaurs}Zentauren{/link} der Galak an, der sich von Osten her nach {link:mulgore}Mulgore{/link} geschlichen hat. Seine Reiter töteten die {link:longwalkers}Langwanderin{/link} Malah Longwind mit Pfeilen in den Rücken und errichteten ein Lager innerhalb der Grenzen der {link:tauren}Tauren{/link}. Herak beansprucht die Ebenen für die Galak und schwört den Tauren Rache. Seine Reiter wollten rasten, bevor sie {link:bloodhoof-village}Bloodhoof{/link} angriffen, und nach Verstärkung ins {link:the-barrens}Brachland{/link} schicken.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Herak ist ein Zeichen, dass die {link:centaurs}Zentauren{/link} {link:mulgore}Mulgore{/link} nicht vergessen haben und dass Cairnes Sieg noch immer verteidigt werden muss.]=],
		},
		{
			title = "Taten",
			text = [=[• Seine Reiter erschlugen die {link:longwalkers}Langwanderin{/link} Malah.
• Er führte einen Raubtrupp nach {link:mulgore}Mulgore{/link}.]=],
		},
	},
	mentions = {
		{ text = "Vertreibt sie" },
	},
	bonds = {
		{ id = "baine-bloodhoof", name = "Baine Bloodhoof", note = "will seinen Kopf" },
	},
})

Translate("deDE", "bristleback-quilboar", {
	title = "Stacheleber der Borstennacken",
	aliases = { "Borstennacken-Stacheleber", "Borstennacken", "Borstennacken-Stamm" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Borstennacken sind der Stamm der {link:quilboar}Stacheleber{/link}, der in {link:mulgore}Mulgore{/link} lebt. Sie waren dort, bevor sich die {link:tauren}Tauren{/link} auf den Ebenen niederließen, und sie liegen seither mit ihnen im Krieg. Von ihrem dornigen Dorf in der {link:brambleblade-ravine}Dornrankenklamm{/link} aus schlagen sie gegen {link:red-cloud-mesa}Red Cloud Mesa{/link} zu, und ihre Plünderer dringen bis zur Begräbnisstätte der {link:red-rocks}Teufelsfelsen{/link} im Norden vor.]=],
		},
		{
			title = "Kriegsweise",
			text = [=[Die Borstennacken kämpfen aus dem Hinterhalt. Ihre Krieger lauern Jagdgruppen der {link:tauren}Tauren{/link} auf und schleichen sich im Dunkeln nach {link:camp-narache}Camp Narache{/link}. Ihre Schamanen kämpfen an ihrer Seite. Sie richten Kampfeber ab, die großen Eber der Klamm, damit sie bösartig werden, und schicken sie in die Jagdgründe der Tauren. Ihr Kriegshäuptling entwarf Pläne für eine lange Belagerung von Camp Narache.]=],
		},
		{
			title = "In diesen Tagen",
			text = [=[Die jungen {link:tauren}Tauren{/link} von {link:camp-narache}Narache{/link} beweisen ihre Stärke gegen die Borstennacken, und die Gürtel gefallener Plünderer sind die ersten Trophäen des Ritus der Stärke. Eindringlinge der Borstennacken haben in letzter Zeit die Gräber in den {link:red-rocks}Teufelsfelsen{/link} verwüstet. Ihr Häuptling, {link:chief-sharptusk-thornmantle}Sharptusk Thornmantle{/link}, herrscht über die Klamm.]=],
		},
	},
})

Translate("deDE", "palemane-gnolls", {
	title = "Gnolle der Bleichmähnen",
	aliases = { "Bleichmähnen-Gnolle", "Bleichmähnen" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Bleichmähnen sind ein Stamm von {link:gnolls}Gnollen{/link}, die sich in {link:mulgore}Mulgore{/link} niedergelassen haben. Sie hausen in der Höhle des Bleichmähnenfelses in den westlichen Hügeln und unterhalten Lager südlich von {link:bloodhoof-village}Bloodhoof{/link}. Sie sind Wilderer, Häuter und Gerber, und sie erlegen das Wild der Ebenen ohne Maß.]=],
		},
		{
			title = "Die Tauren und die Bleichmähnen",
			text = [=[Die {link:tauren}Tauren{/link} versuchten, das Land mit ihnen zu teilen. Immer wieder suchten sie das Gespräch mit den Gnollen, und jedes Mal stießen sie auf Respektlosigkeit. Häuptling {link:baine-bloodhoof}Baine Bloodhoof{/link} urteilte schließlich, dass Worte nicht länger die Antwort seien. Dennoch unternahm der Hochhäuptling in diesen Tagen einen weiteren Versuch und schickte seinen {link:longwalkers}Langwanderer{/link} {link:perith-stormhoof}Perith Stormhoof{/link} zu ihnen. Die {link:gnolls}Gnolle{/link} ergriffen ihn und hielten ihn in ihrer Höhle fest.]=],
		},
		{
			title = "Ihre Reviere",
			text = [=[Die Gerber und Häuter des Stammes bearbeiten die Felle ihrer Beute rund um den {link:palemane-rock}Bleichmähnenfels{/link}, während Wilderer durch die westlichen Hügel streifen. Zwischen den {link:camping}Lagern{/link} südlich von {link:bloodhoof-village}Bloodhoof{/link} schleicht ein {link:gnolls}Gnoll{/link} namens Snagglespear umher.]=],
		},
	},
})

Translate("deDE", "windfury-harpies", {
	title = "Harpyien der Windfurien",
	aliases = { "Windfurien-Harpyien", "Windfurien" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Windfurien sind die {link:harpies}Harpyien{/link} von {link:mulgore}Mulgore{/link}. Ihre Schwärme nisten an den Bergrändern im Südosten, abseits der Straßen, und vor allem auf dem {link:windfury-ridge}Windfurienkamm{/link} im hohen Norden. Die {link:tauren}Tauren{/link} zählen sie zu den natürlichen Feinden ihres Landes.]=],
		},
		{
			title = "Wesen",
			text = [=[Die Schwärme der Windfurien werden von Matriarchinnen beherrscht, und ihre Hexen und Zauberinnen gebieten über den Wind. Sie machen Jagd auf alles, was unter ihren Nistplätzen umhergeht. Ihr Gefieder wird von den {link:tauren}Tauren{/link} geschätzt: Die azurblauen und bronzenen Federn der nördlichen Schwärme werden für den Kopfschmuck verwendet, den junge Tauren tragen, wenn sie vor den Hochhäuptling treten.]=],
		},
		{
			title = "In diesen Tagen",
			text = [=[{link:ruul-eagletalon}Ruul Eagletalon{/link} aus {link:bloodhoof-village}Bloodhoof{/link} schickt junge Krieger als Prüfung ihrer Stärke gegen die Schwärme des Südostens. Die nördlichen Schwärme sind stärker, und ihre Zauberinnen und Matriarchinnen beherrschen die Höhen des Windfurienkamms. Eine {link:harpies}Harpyie{/link} namens Schwester Hatelash wurde zwischen den nordwestlichen Felsen gesehen, nicht weit von dem Plateau, auf dem der Irdene Ring sein Lager aufgeschlagen hat.]=],
		},
	},
})

Translate("deDE", "longwalkers", {
	title = "Langwanderer",
	aliases = { "Langwanderin" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Langwanderer sind die vertrautesten Späher der {link:tauren}Tauren{/link}. Sie sind allein dem Hochhäuptling {link:cairne-bloodhoof}Cairne Bloodhoof{/link} verpflichtet, und sie führen seine geheimsten Aufträge aus. Einen Langwanderer erkennt man an einem Stirnband und einem gefiederten Stab. Selbst der Häuptling von {link:bloodhoof-village}Bloodhoof{/link}, Cairnes eigener Sohn, kann sie nur um ihre Hilfe bitten.]=],
		},
		{
			title = "Ihre Bräuche",
			text = [=[Verschwiegenheit ist das erste Gesetz der Langwanderer. Sie reisen allein, sie sprechen nicht über ihre Aufträge, und wenn einer aus einer Gefahr gerettet wird, zieht er lieber allein weiter, als jemandem zu sagen, wohin er geht. Wenn ein Langwanderer nicht von einer Wache zurückkehrt, müssen die Tapferen des nächsten Dorfes hinausgehen und herausfinden, warum.]=],
		},
		{
			title = "In diesen Tagen",
			text = [=[Zwei Langwanderer sind in {link:mulgore}Mulgore{/link} in Gefahr geraten. {link:perith-stormhoof}Perith Stormhoof{/link}, den {link:cairne-bloodhoof}Cairne{/link} seinen vertrautesten Späher nennt, wurde ausgesandt, um mit den Gnollen der {link:palemane-gnolls}Bleichmähnen{/link} zu verhandeln, und wurde gefangen genommen. Malah Longwind wurde ausgesandt, um die Ostgrenze zu beobachten, und wurde von {link:centaurs}Zentauren{/link} der Galak erschlagen, ihren Bericht noch in der Hand.]=],
		},
	},
})

Translate("deDE", "rites-of-the-earthmother", {
	title = "Riten der Erdenmutter",
	aliases = { "Riten der Erdmutter" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Riten der Erdenmutter sind die Prüfungen, durch die sich ein junger {link:tauren}Tauren{/link} den Respekt der Ältesten von {link:thunder-bluff}Thunder Bluff{/link} verdient. Es gibt drei: den Ritus der Stärke, den Ritus der Vision und den Ritus der Weisheit. Zusammen führen sie vom ersten Lager auf {link:red-cloud-mesa}Red Cloud Mesa{/link} bis zur Halle des Hochhäuptlings.]=],
		},
		{
			title = "Die drei Riten",
			text = [=[• {b}Der Ritus der Stärke.{/b} {link:chief-hawkwind}Häuptling Hawkwind{/link} und der {link:seer-graytongue}Seher Graytongue{/link} schicken die Jungen gegen die Plünderer der {link:bristleback-quilboar}Borstennacken{/link} in der {link:brambleblade-ravine}Dornrankenklamm{/link}, um ihre Gürtel als Beweis ihrer Tapferkeit zurückzubringen.
• {b}Der Ritus der Vision.{/b} In {link:bloodhoof-village}Bloodhoof{/link} braut {link:zarlman-two-moons}Zarlman Two-Moons{/link} das Wasser der Seher aus Brunnensteinen und Ambereicheln. Vor dem Stammesfeuer getrunken, ruft es eine Vision der Ebenen herbei, die den Trinkenden zum {link:seer-wiserunner}Seher Wiserunner{/link} führt.
• {b}Der Ritus der Weisheit.{/b} In den {link:red-rocks}Teufelsfelsen{/link} geben die Ahnengeister jenen ihren Segen, die vom Wasser der Seher getrunken haben.]=],
		},
		{
			title = "Das Ende der Reise",
			text = [=[Wer die Riten besteht, wird in {link:thunder-bluff}Thunder Bluff{/link} geehrt. Sein letzter Schritt ist, auf den höchsten Tafelberg zu steigen und vor {link:cairne-bloodhoof}Cairne Bloodhoof{/link} zu treten. Selbst dann ist die Prüfung nicht vorüber. Um den errungenen Platz zu behalten, schickt der Hochhäuptling sie aus, um Arra'chea zu verfolgen und zu erlegen, einen mächtigen Kodo der Ebenen.]=],
		},
	},
})
